import api from './api';

const phoneService = {
  // 获取所有手机
  getPhones: async () => {
    const response = await api.get('/phones');
    return response.data;
  },

  // 获取单个手机详情
  getPhoneById: async (id) => {
    const response = await api.get(`/phones/${id}`);
    return response.data;
  },

  // 添加到收藏
  addToFavorite: async (phoneId) => {
    const response = await api.post('/users/favorites', { phoneId });
    return response.data;
  },

  // 从收藏中移除
  removeFromFavorite: async (phoneId) => {
    const response = await api.delete(`/users/favorites/${phoneId}`);
    return response.data;
  },

  // 创建新手机 (管理员)
  createPhone: async (phoneData) => {
    const response = await api.post('/phones', phoneData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    });
    return response.data;
  },

  // 更新手机信息 (管理员)
  updatePhone: async (id, phoneData) => {
    const response = await api.put(`/phones/${id}`, phoneData, {
      headers: {
        'Content-Type': 'multipart/form-data',
      },
    });
    return response.data;
  },

  // 删除手机 (管理员)
  deletePhone: async (id) => {
    const response = await api.delete(`/phones/${id}`);
    return response.data;
  },
};

export default phoneService;
